int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==7,"original packet sites guard retained-positive-run NEW-output 225|137");size_t it=atoi(argv[6]);need(it==225||it==137,"same physical inputs only");auto p=curved::read(argv[1]);auto sites=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],sites);std::string saved=argv[4],dest=argv[5];const auto&r=p.record[it];Q anchor[2];curved_bounds::Tri tri;for(int k=0;k<2;k++){S x;for(int a=0;a<3;a++){x=x+S(Q(r.triangle.geometry.x[a][k]))/S(3);tri[a][k]=r.triangle.geometry.x[a][k];}anchor[k]=x.n;}auto map=tg::compile(r,anchor,p.parameters[3]);int own=-1;for(size_t j=0;j<sites.size();j++)if(sites[j].id==r.cell)own=j;need(own>=0,"source owner");auto old_bound=positive_source_bounds(r,tri,p.parameters[3]);auto possible=source_candidates(r,old_bound,sites,weights,own);auto started=std::chrono::steady_clock::now();
    std::ofstream sectors(dest+"/sector_certificates.csv"),errors(dest+"/analytic_remainders.csv");sectors<<"target,loop,boundary,sector,pass,reason,reference_radius_x,reference_radius_y,physical_radius_x,physical_radius_y,contraction,invariance_ratio,analytic_fan_J_bound,K_remainder,U_remainder,potential_remainder,Udot_remainder\n";errors<<"source,target,moment,all_sectors_complete,analytic_remainder\n";uint64_t failed=0,count=0;Q maximum=0;for(int target:possible)if(target!=own){auto domain=td::build(map,r,sites,weights,target);Q total[NMOMENT]={};bool pass=true;for(size_t il=0;il<domain.loop.size();il++){auto&loop=domain.loop[il];for(int ib:loop.boundary)for(int sector=0;sector<4;sector++){auto c=ta::sector(p,r,map,domain,loop,domain.boundary[ib],sector);count++;failed+=!c.pass;pass=pass&&c.pass;sectors<<sites[target].id<<','<<il<<','<<ib<<','<<sector<<','<<c.pass<<','<<c.reason<<','<<qs(c.ref_radius[0])<<','<<qs(c.ref_radius[1])<<','<<qs(c.physical_radius[0])<<','<<qs(c.physical_radius[1])<<','<<qs(c.contraction)<<','<<qs(c.invariance_ratio)<<','<<qs(c.Jfan);for(int k:{KINETIC,THERMAL,POTENTIAL,THERMAL_RATE})sectors<<','<<(c.pass?qs(c.remainder[k]):"unproved");sectors<<'\n';if(c.pass)for(int k=0;k<NMOMENT;k++)total[k]=ti::add(total[k],c.remainder[k]);}}
        for(int k=0;k<NMOMENT;k++){errors<<r.cell<<','<<sites[target].id<<','<<moment_names[k]<<','<<pass<<','<<(pass?qs(total[k]):"unproved")<<'\n';if(pass)maximum=std::max(maximum,total[k]);}}
    sectors.close();errors.close();printf("{\"scope\":\"same native physical positive-domain quadrature; fixed Gauss16 Cauchy radius3/4, complex original P3+v0 map and inverse/field/profile/potential branch certificates; no positive-point recomputation, state or tolerance change\",\"triangle\":%zu,\"sectors_checked\":%llu,\"failed_sectors\":%llu,\"analytic_remainder_complete\":%s,\"source_baseline_and_gluing_complete\":false,\"full_cold_transfer_proved\":false,\"max_completed_moment_remainder\":%.17Lg,\"seconds\":%.17g}\n",it,(unsigned long long)count,(unsigned long long)failed,failed?"false":"true",R(maximum),std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count());active_mpi=false;MPI_Finalize();return failed?2:0;}
